#pragma once

// Simple fonts' encodings and glyph names (ISO 32000-2 §9.6.5, Annex D):
// the built-in encodings as 256 glyph names, a glyph name's Unicode value
// — from the table, or from the names that carry their value (uniXXXX,
// uXXXX, the afii Cyrillic names, a name with a .suffix or _ ligature
// parts) — and the 258 standard Macintosh names a TrueType 'post' table
// counts from. The data is generated by tools/gen-pdf-encodings.py.

#include <array>
#include <optional>
#include <span>
#include <string>
#include <string_view>

namespace sashfold::pdf {

struct GlyphUnicode {
    char const* name;
    char32_t unicode;
};

namespace encoding_data {
extern std::array<char const*, 256> const k_standard;
extern std::array<char const*, 256> const k_win_ansi;
extern std::array<char const*, 256> const k_mac_roman;
extern std::array<char const*, 256> const k_symbol;
extern std::array<char const*, 256> const k_zapf_dingbats;
extern std::array<char const*, 258> const k_mac_glyph_names;
}
// Every glyph name the tables know, sorted by name (EncodingData.cpp).
std::span<GlyphUnicode const> glyph_unicode_table();

enum class BaseEncoding { Standard, WinAnsi, MacRoman, MacExpert, Symbol, ZapfDingbats };

// The encoding's glyph names by code; null where it has none. MacExpert
// (old small-caps sets) is read as Standard, as most viewers do.
std::array<char const*, 256> const& base_encoding(BaseEncoding encoding);
std::optional<BaseEncoding> base_encoding_named(std::string_view name);

// The text a glyph name stands for; empty when nothing says.
std::u32string glyph_name_unicode(std::string_view name);
// The code a name has in an encoding, when it has one there.
std::optional<int> code_in(std::array<char const*, 256> const& encoding, std::string_view name);

// The standard Macintosh glyph name at an index below 258.
char const* mac_glyph_name(int index);

}
